// WhatsApp packet orchestrator.
// Packet mutation authority belongs to Core RPC stitch_whatsapp_messages_atomic;
// this Edge Function discovers/groups inbound rows, backfills packet-complete
// commercial evidence, then invokes the Core-owned AI worker automatically.
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient, type SupabaseClient } from "npm:@supabase/supabase-js@2.45.0";
import { flushGovernedWhatsappBuffer } from "../_shared/whatsappBufferReconciler.ts";
import { groupMessagesByStitchingWindow, partitionUnstitchedByContactAuthority } from "../_shared/whatsappStitchingWindow.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

type UnstitchedMessage = {
  id: string;
  contact_id: string;
  direction: string;
  content: string | null;
  created_at: string;
  message_timestamp: string | null;
  provider_message_id: string | null;
};

type SourceMessage = {
  id: string;
  provider_message_id: string;
  message_type: string | null;
};

type StitcherRequest = {
  windowSeconds?: number;
  batchSize?: number;
  providerMessageId?: string;
  provider_message_id?: string;
  bufferId?: string;
  buffer_id?: string;
};

type PacketFailure = { packetId: string; error: string };

const DEFAULT_WINDOW_SECONDS = 300;
const DEFAULT_BATCH_SIZE = 100;
const AI_WORKER_CONCURRENCY = 3;

async function syncCommercialEvidenceForPacket(
  admin: SupabaseClient,
  packetId: string,
): Promise<{ linked: number; potentialOrderId: string | null }> {
  const { data: packetMessages, error: packetMessagesError } = await admin
    .from("whatsapp_messages")
    .select("provider_message_id")
    .eq("packet_id", packetId)
    .eq("direction", "inbound")
    .order("packet_sequence", { ascending: true });
  if (packetMessagesError) throw new Error(`Packet evidence lookup failed: ${packetMessagesError.message}`);

  const providerIds = [...new Set((packetMessages ?? [])
    .map((row) => String(row.provider_message_id ?? "").trim())
    .filter(Boolean))];
  if (providerIds.length === 0) return { linked: 0, potentialOrderId: null };

  const { data: anchors, error: anchorError } = await admin
    .from("whatsapp_commercial_evidence")
    .select("potential_order_id")
    .in("provider_message_id", providerIds)
    .order("captured_at", { ascending: true })
    .limit(1);
  if (anchorError) throw new Error(`Commercial anchor lookup failed: ${anchorError.message}`);
  const anchorPotentialId = String(anchors?.[0]?.potential_order_id ?? "").trim();
  if (!anchorPotentialId) return { linked: 0, potentialOrderId: null };

  const { data: sources, error: sourceError } = await admin
    .from("whatsapp_inbound_messages")
    .select("id, provider_message_id, message_type")
    .in("provider_message_id", providerIds)
    .order("received_at", { ascending: true });
  if (sourceError) throw new Error(`Core source lookup failed: ${sourceError.message}`);

  let linked = 0;
  let potentialOrderId = anchorPotentialId;
  for (const source of (sources ?? []) as SourceMessage[]) {
    const { data: potential, error: potentialError } = await admin.rpc("capture_whatsapp_potential_order", {
      p_source_message_id: source.id,
      p_order_like: true,
      p_interpretation_failed: false,
      p_evidence: {
        packet_context_backfill: true,
        message_packet_id: packetId,
        authority: "stitcher_packet_complete",
      },
    });
    if (potentialError || !potential?.id) {
      throw new Error(`Packet potential lineage failed: ${potentialError?.message ?? "missing potential order"}`);
    }
    potentialOrderId = String(potential.id);

    const messageType = String(source.message_type ?? "text").toLowerCase();
    const { error: evidenceError } = await admin.rpc("capture_whatsapp_commercial_fragment_for_potential", {
      p_potential_order_id: potentialOrderId,
      p_source_message_id: source.id,
      p_media_count: messageType === "text" ? 0 : 1,
      p_interpretation_failed: false,
      p_evidence: {
        packet_context_backfill: true,
        message_packet_id: packetId,
        authority: "stitcher_packet_complete",
      },
    });
    if (evidenceError) throw new Error(`Packet commercial evidence failed: ${evidenceError.message}`);
    linked += 1;
  }

  return { linked, potentialOrderId };
}

async function resolveRecoveryPacketId(
  admin: SupabaseClient,
  providerMessageId: string,
): Promise<string | null> {
  const normalized = providerMessageId.trim();
  if (!normalized) return null;
  const { data, error } = await admin
    .from("whatsapp_messages")
    .select("packet_id")
    .eq("provider_message_id", normalized)
    .not("packet_id", "is", null)
    .order("created_at", { ascending: false })
    .order("id", { ascending: false })
    .limit(1);
  if (error) throw new Error(`Recovery packet lookup failed: ${error.message}`);
  const packetId = String(data?.[0]?.packet_id ?? "").trim();
  return packetId || null;
}

async function invokePacketAiWorker(
  supabaseUrl: string,
  serviceKey: string,
  packetId: string,
): Promise<{ packetId: string; ok: boolean; status: number; error?: string }> {
  try {
    const response = await fetch(`${supabaseUrl.replace(/\/$/, "")}/functions/v1/whatsapp-packet-ai-worker`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${serviceKey}`,
      },
      body: JSON.stringify({ packet_id: packetId }),
      signal: AbortSignal.timeout(70_000),
    });
    const body = await response.json().catch(() => ({})) as Record<string, unknown>;
    return {
      packetId,
      ok: response.ok && body.success === true,
      status: response.status,
      ...(response.ok && body.success === true ? {} : { error: String(body.error ?? `HTTP_${response.status}`) }),
    };
  } catch (error) {
    return { packetId, ok: false, status: 0, error: error instanceof Error ? error.message : "AI_WORKER_FAILED" };
  }
}

async function runAiWorkersBounded(
  supabaseUrl: string,
  serviceKey: string,
  packetIds: string[],
): Promise<Array<{ packetId: string; ok: boolean; status: number; error?: string }>> {
  const results: Array<{ packetId: string; ok: boolean; status: number; error?: string }> = [];
  let cursor = 0;
  const workers = Array.from({ length: Math.min(AI_WORKER_CONCURRENCY, packetIds.length) }, async () => {
    for (;;) {
      const index = cursor;
      cursor += 1;
      if (index >= packetIds.length) return;
      results[index] = await invokePacketAiWorker(supabaseUrl, serviceKey, packetIds[index]);
    }
  });
  await Promise.all(workers);
  return results;
}

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), { status: 405, headers: { ...corsHeaders, "Content-Type": "application/json" } });
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  if (!supabaseUrl || !serviceKey) {
    return new Response(JSON.stringify({ success: false, error: "Service configuration unavailable" }), { status: 503, headers: { ...corsHeaders, "Content-Type": "application/json" } });
  }
  if ((req.headers.get("Authorization") ?? "") !== `Bearer ${serviceKey}`) {
    return new Response(JSON.stringify({ success: false, error: "Trusted stitcher caller required" }), { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } });
  }

  try {
    const body = await req.json().catch(() => ({})) as StitcherRequest;
    const windowSeconds = Math.min(3600, Math.max(30, Number(body.windowSeconds) || DEFAULT_WINDOW_SECONDS));
    const batchSize = Math.min(500, Math.max(1, Number(body.batchSize) || DEFAULT_BATCH_SIZE));
    const recoveryProviderMessageId = String(body.providerMessageId ?? body.provider_message_id ?? "").trim();
    const replayBufferId = String(body.bufferId ?? body.buffer_id ?? "").trim();
    const admin = createClient(supabaseUrl, serviceKey);

    const { data, error } = await admin
      .from("whatsapp_messages")
      .select("id, contact_id, direction, content, created_at, message_timestamp, provider_message_id")
      .eq("is_raw", true)
      .is("packet_id", null)
      .eq("direction", "inbound")
      .order("created_at", { ascending: true })
      .limit(batchSize);
    if (error) throw new Error(`Failed to find unstitched messages: ${error.message}`);

    const unstitched = (data ?? []) as UnstitchedMessage[];
    const { stitchable, rejectedIds } = partitionUnstitchedByContactAuthority(unstitched);
    if (rejectedIds.length > 0) {
      console.warn(
        "[whatsapp-message-stitcher] quarantined unstitched rows missing contact authority",
        JSON.stringify({ rejectedIds }),
      );
    }

    const groupsByContact = groupMessagesByStitchingWindow(stitchable, windowSeconds);
    let groupsProcessed = 0;
    let fragmentsLinked = 0;
    let commercialFragmentsLinked = 0;
    const packetIds = new Set<string>();

    const recoveryPacketId = await resolveRecoveryPacketId(admin, recoveryProviderMessageId);
    if (recoveryPacketId) packetIds.add(recoveryPacketId);

    for (const contact of groupsByContact) {
      for (const group of contact.groups) {
        if (group.messages.length === 0) continue;
        const { data: packetId, error: rpcError } = await admin.rpc("stitch_whatsapp_messages_atomic", {
          p_contact_id: contact.contact_id,
          p_message_ids: group.messages.map((m) => m.id),
          p_window_seconds: windowSeconds,
        });
        if (rpcError || !packetId) {
          throw new Error(`Core packet authority failed for contact ${contact.contact_id}: ${rpcError?.message ?? "missing packet id"}`);
        }
        packetIds.add(String(packetId));
        groupsProcessed += 1;
        fragmentsLinked += group.messages.length;
      }
    }

    const commercialFailures: PacketFailure[] = [];
    for (const packetId of packetIds) {
      try {
        const commercialSync = await syncCommercialEvidenceForPacket(admin, packetId);
        commercialFragmentsLinked += commercialSync.linked;
      } catch (error) {
        commercialFailures.push({
          packetId,
          error: error instanceof Error ? error.message : "COMMERCIAL_SYNC_FAILED",
        });
      }
    }
    if (commercialFailures.length > 0) {
      console.warn("[whatsapp-message-stitcher] commercial sync failures", JSON.stringify(commercialFailures));
    }

    const packetIdList = [...packetIds];
    const aiResults = await runAiWorkersBounded(supabaseUrl, serviceKey, packetIdList);
    const aiFailures = aiResults.filter((result) => !result.ok);
    if (aiFailures.length > 0) {
      console.warn("[whatsapp-message-stitcher] packet AI failures", JSON.stringify(aiFailures));
    }

    let bufferFlush = {
      rowsFlushed: 0,
      sendersProcessed: 0,
      sendersWaiting: 0,
      staleFlushingRecovered: 0,
      flushedBufferIds: [] as string[],
      linkedPacketIds: [] as string[],
    };
    try {
      bufferFlush = await flushGovernedWhatsappBuffer(admin, {
        bufferIds: replayBufferId ? [replayBufferId] : undefined,
        idleSeconds: replayBufferId ? 0 : undefined,
      });
    } catch (bufferError) {
      console.warn(
        "[whatsapp-message-stitcher] buffer flush failed",
        bufferError instanceof Error ? bufferError.message : String(bufferError),
      );
    }

    const hasFailures = commercialFailures.length > 0 || aiFailures.length > 0;
    return new Response(JSON.stringify({
      success: !hasFailures,
      ok: !hasFailures,
      messagesProcessed: stitchable.length,
      messagesQuarantined: rejectedIds.length,
      quarantinedMessageIds: rejectedIds,
      groupsProcessed,
      fragmentsLinked,
      commercialFragmentsLinked,
      commercialFailures,
      packetIds: packetIdList,
      recoveryProviderMessageId: recoveryProviderMessageId || null,
      replayBufferId: replayBufferId || null,
      bufferFlush,
      aiResults,
      config: { windowSeconds, batchSize, aiWorkerConcurrency: AI_WORKER_CONCURRENCY },
    }), { status: hasFailures ? 207 : 200, headers: { ...corsHeaders, "Content-Type": "application/json" } });
  } catch (e) {
    const message = e instanceof Error ? e.message : "Unknown error";
    console.error("[whatsapp-message-stitcher]", message);
    return new Response(JSON.stringify({ success: false, ok: false, error: message }), { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } });
  }
});

// Idempotent whatsapp_buffer housekeeping after governed packet stitching.
// Does not create orders, suggested_orders, or duplicate packets — only marks
// buffer rows flushed once linked whatsapp_messages have packet_id set.

import type { SupabaseClient } from "npm:@supabase/supabase-js@2.45.0";
import {
  BUFFER_IDLE_SECONDS,
  type BufferRow,
  earliestCreatedAtBySender,
  isStaleFlushingRow,
  latestCreatedAtBySender,
  normalizeSenderPhoneLast10,
  pickIdleSenders,
  to91FromSenderLast10,
} from "./whatsappBufferReconcilerPure.ts";

export {
  BUFFER_IDLE_SECONDS,
  BUFFER_FLUSHING_STALE_SECONDS,
  type BufferRow,
  earliestCreatedAtBySender,
  isStaleFlushingRow,
  latestCreatedAtBySender,
  normalizeSenderPhoneLast10,
  pickIdleSenders,
  to91FromSenderLast10,
} from "./whatsappBufferReconcilerPure.ts";

async function contactIdForSender(admin: SupabaseClient, senderLast10: string): Promise<string | null> {
  const phone91 = to91FromSenderLast10(senderLast10);
  if (!phone91) return null;
  const { data, error } = await admin
    .from("whatsapp_contacts")
    .select("id")
    .eq("phone_number", phone91)
    .maybeSingle();
  if (error || !data?.id) return null;
  return String(data.id);
}

export async function senderHasStitchedPacket(
  admin: SupabaseClient,
  senderLast10: string,
  sinceIso: string,
): Promise<{
  hasPacket: boolean;
  packetIds: string[];
}> {
  const contactId = await contactIdForSender(admin, senderLast10);
  if (!contactId) return { hasPacket: false, packetIds: [] };
  if (!Number.isFinite(Date.parse(sinceIso))) return { hasPacket: false, packetIds: [] };

  const { data, error } = await admin
    .from("whatsapp_messages")
    .select("packet_id")
    .eq("contact_id", contactId)
    .eq("direction", "inbound")
    .not("packet_id", "is", null)
    .gte("created_at", sinceIso)
    .order("created_at", { ascending: false })
    .limit(20);
  if (error) throw new Error(`BUFFER_PACKET_LOOKUP_FAILED: ${error.message}`);

  const packetIds = [...new Set((data ?? [])
    .map((row) => String(row.packet_id ?? "").trim())
    .filter(Boolean))];
  return { hasPacket: packetIds.length > 0, packetIds };
}

export type BufferFlushResult = {
  rowsFlushed: number;
  sendersProcessed: number;
  sendersWaiting: number;
  staleFlushingRecovered: number;
  flushedBufferIds: string[];
  linkedPacketIds: string[];
};

export async function flushGovernedWhatsappBuffer(
  admin: SupabaseClient,
  options: { bufferIds?: string[]; idleSeconds?: number; now?: Date } = {},
): Promise<BufferFlushResult> {
  const now = options.now ?? new Date();
  const nowMs = now.getTime();
  const idleSeconds = options.idleSeconds ?? BUFFER_IDLE_SECONDS;
  const cutoffIso = new Date(nowMs - idleSeconds * 1000).toISOString();
  const targetBufferIds = (options.bufferIds ?? []).map((id) => id.trim()).filter(Boolean);

  const { data: flushingRows, error: flushingError } = await admin
    .from("whatsapp_buffer")
    .select("id, sender_phone, created_at, bundle_status")
    .eq("bundle_status", "flushing");
  if (flushingError) throw new Error(`BUFFER_FLUSHING_LOOKUP_FAILED: ${flushingError.message}`);

  const staleFlushingIds = (flushingRows ?? [])
    .filter((row) => isStaleFlushingRow(row.created_at, nowMs))
    .map((row) => row.id);
  if (staleFlushingIds.length > 0) {
    const { error } = await admin
      .from("whatsapp_buffer")
      .update({ bundle_status: "pending" })
      .in("id", staleFlushingIds);
    if (error) throw new Error(`BUFFER_FLUSHING_RECOVERY_FAILED: ${error.message}`);
  }

  let pendingQuery = admin
    .from("whatsapp_buffer")
    .select("id, sender_phone, created_at, bundle_status")
    .in("bundle_status", ["pending", "flushing"]);
  if (targetBufferIds.length > 0) pendingQuery = pendingQuery.in("id", targetBufferIds);

  const { data: pending, error: pendingError } = await pendingQuery;
  if (pendingError) throw new Error(`BUFFER_PENDING_LOOKUP_FAILED: ${pendingError.message}`);

  const pendingRows = (pending ?? []) as BufferRow[];
  if (!pendingRows.length) {
    return {
      rowsFlushed: 0,
      sendersProcessed: 0,
      sendersWaiting: 0,
      staleFlushingRecovered: staleFlushingIds.length,
      flushedBufferIds: [],
      linkedPacketIds: [],
    };
  }

  const senderLatest = latestCreatedAtBySender(pendingRows);
  const senderEarliest = earliestCreatedAtBySender(pendingRows);
  const idleSenders = new Set(pickIdleSenders(senderLatest, cutoffIso));
  const sendersToProcess = targetBufferIds.length > 0
    ? [...new Set(pendingRows.map((row) => normalizeSenderPhoneLast10(row.sender_phone)).filter(Boolean))]
    : [...idleSenders];

  const pendingBySender = new Map<string, string[]>();
  for (const row of pendingRows) {
    const sender = normalizeSenderPhoneLast10(row.sender_phone);
    if (!sender) continue;
    const bucket = pendingBySender.get(sender) ?? [];
    bucket.push(row.id);
    pendingBySender.set(sender, bucket);
  }

  let rowsFlushed = 0;
  let sendersProcessed = 0;
  let sendersWaiting = 0;
  const flushedBufferIds: string[] = [];
  const linkedPacketIds: string[] = [];

  for (const sender of sendersToProcess) {
    if (!targetBufferIds.length && !idleSenders.has(sender)) {
      sendersWaiting += 1;
      continue;
    }

    const earliestPendingAt = senderEarliest.get(sender);
    if (!earliestPendingAt) {
      sendersWaiting += 1;
      continue;
    }

    const { hasPacket, packetIds } = await senderHasStitchedPacket(admin, sender, earliestPendingAt);
    if (!hasPacket) {
      if (!targetBufferIds.length) sendersWaiting += 1;
      continue;
    }

    const rowIds = pendingBySender.get(sender) ?? [];
    if (!rowIds.length) continue;

    const { data: lockedRows, error: lockError } = await admin
      .from("whatsapp_buffer")
      .update({ bundle_status: "flushing" })
      .in("id", rowIds)
      .in("bundle_status", ["pending", "flushing"])
      .select("id");
    if (lockError || !lockedRows?.length) continue;

    const ids = lockedRows.map((row) => row.id);
    const flushedAt = now.toISOString();
    const { error: flushError } = await admin
      .from("whatsapp_buffer")
      .update({ bundle_status: "flushed", flushed_at: flushedAt })
      .in("id", ids);
    if (flushError) {
      await admin.from("whatsapp_buffer").update({ bundle_status: "pending" }).in("id", ids);
      throw new Error(`BUFFER_FLUSH_FAILED: ${flushError.message}`);
    }

    rowsFlushed += ids.length;
    sendersProcessed += 1;
    flushedBufferIds.push(...ids);
    linkedPacketIds.push(...packetIds);
  }

  return {
    rowsFlushed,
    sendersProcessed,
    sendersWaiting,
    staleFlushingRecovered: staleFlushingIds.length,
    flushedBufferIds,
    linkedPacketIds: [...new Set(linkedPacketIds)],
  };
}

export const BUFFER_IDLE_SECONDS = 60;
export const BUFFER_FLUSHING_STALE_SECONDS = 5 * 60;

export type BufferRow = {
  id: string;
  sender_phone: string;
  created_at: string;
  bundle_status: string;
};

export function normalizeSenderPhoneLast10(raw: string): string {
  const digits = (raw || "").replace(/\D/g, "");
  return digits.length >= 10 ? digits.slice(-10) : digits;
}

export function to91FromSenderLast10(senderLast10: string): string {
  const last10 = normalizeSenderPhoneLast10(senderLast10);
  if (last10.length !== 10) return last10;
  return `91${last10}`;
}

export function latestCreatedAtBySender(rows: BufferRow[]): Map<string, string> {
  const senderLatest = new Map<string, string>();
  for (const row of rows) {
    const sender = normalizeSenderPhoneLast10(row.sender_phone);
    if (!sender) continue;
    const rowMs = Date.parse(row.created_at);
    if (!Number.isFinite(rowMs)) continue;
    const existing = senderLatest.get(sender);
    if (!existing || rowMs > Date.parse(existing)) senderLatest.set(sender, row.created_at);
  }
  return senderLatest;
}

export function earliestCreatedAtBySender(rows: BufferRow[]): Map<string, string> {
  const senderEarliest = new Map<string, string>();
  for (const row of rows) {
    const sender = normalizeSenderPhoneLast10(row.sender_phone);
    if (!sender) continue;
    const rowMs = Date.parse(row.created_at);
    if (!Number.isFinite(rowMs)) continue;
    const existing = senderEarliest.get(sender);
    if (!existing || rowMs < Date.parse(existing)) senderEarliest.set(sender, row.created_at);
  }
  return senderEarliest;
}

export function pickIdleSenders(senderLatest: Map<string, string>, cutoffIso: string): string[] {
  const cutoffMs = Date.parse(cutoffIso);
  if (!Number.isFinite(cutoffMs)) return [];
  const eligible: string[] = [];
  for (const [sender, latest] of senderLatest) {
    const latestMs = Date.parse(latest);
    if (Number.isFinite(latestMs) && latestMs < cutoffMs) eligible.push(sender);
  }
  return eligible;
}

export function isStaleFlushingRow(createdAtIso: string, nowMs: number): boolean {
  const createdMs = Date.parse(createdAtIso);
  if (!Number.isFinite(createdMs)) return false;
  return nowMs - createdMs >= BUFFER_FLUSHING_STALE_SECONDS * 1000;
}

export interface StitchableMessage {
  id: string;
  contact_id: string;
  content: string | null;
  created_at: string;
  provider_message_id?: string | null;
}

export interface StitchingWindowGroup<T extends StitchableMessage = StitchableMessage> {
  messages: T[];
  first_message_at: string;
  last_message_at: string;
}

export interface ContactStitchingGroups<T extends StitchableMessage = StitchableMessage> {
  contact_id: string;
  groups: StitchingWindowGroup<T>[];
}

export function groupMessagesByStitchingWindow<T extends StitchableMessage>(
  unstitchedMessages: T[],
  windowSeconds: number,
): ContactStitchingGroups<T>[] {
  const groupedByContact: { [key: string]: T[] } = {};
  for (const msg of unstitchedMessages) {
    const contactId = String(msg.contact_id ?? "");
    if (!contactId) continue;
    if (!groupedByContact[contactId]) groupedByContact[contactId] = [];
    groupedByContact[contactId].push(msg);
  }
  const packetsByContact: ContactStitchingGroups<T>[] = [];
  for (const [contactId, messages] of Object.entries(groupedByContact)) {
    const groups: StitchingWindowGroup<T>[] = [];
    let currentGroup: StitchingWindowGroup<T> = {
      messages: [],
      first_message_at: String(messages[0].created_at),
      last_message_at: String(messages[0].created_at),
    };
    for (const msg of messages) {
      const msgTime = new Date(String(msg.created_at)).getTime();
      const lastTime = new Date(currentGroup.last_message_at).getTime();
      const timeDiffSeconds = (msgTime - lastTime) / 1000;
      if (timeDiffSeconds <= windowSeconds && currentGroup.messages.length > 0) {
        currentGroup.messages.push(msg);
        currentGroup.last_message_at = String(msg.created_at);
      } else if (currentGroup.messages.length === 0) {
        currentGroup.messages.push(msg);
        currentGroup.first_message_at = String(msg.created_at);
        currentGroup.last_message_at = String(msg.created_at);
      } else {
        groups.push(currentGroup);
        currentGroup = {
          messages: [msg],
          first_message_at: String(msg.created_at),
          last_message_at: String(msg.created_at),
        };
      }
    }
    if (currentGroup.messages.length > 0) groups.push(currentGroup);
    packetsByContact.push({ contact_id: contactId, groups });
  }
  return packetsByContact;
}

export function isWithinAppendWindow(
  existingLastMessageAt: string,
  newEarliestMessageAt: string,
  windowSeconds: number,
): boolean {
  const gapSeconds = (new Date(newEarliestMessageAt).getTime() - new Date(existingLastMessageAt).getTime()) / 1000;
  return gapSeconds >= 0 && gapSeconds <= windowSeconds;
}

export interface DuplicatePartitionResult<T extends StitchableMessage> {
  primary: T[];
  duplicates: T[];
}

export function partitionDuplicateProviderMessages<T extends StitchableMessage>(
  messages: T[],
): DuplicatePartitionResult<T> {
  const seen = new Set<string>();
  const primary: T[] = [];
  const duplicates: T[] = [];
  for (const message of messages) {
    const providerMessageId = message.provider_message_id?.trim();
    if (!providerMessageId) {
      primary.push(message);
      continue;
    }
    if (seen.has(providerMessageId)) {
      duplicates.push(message);
      continue;
    }
    seen.add(providerMessageId);
    primary.push(message);
  }
  return { primary, duplicates };
}

export function stitchedTextFor(messages: Pick<StitchableMessage, "content">[]): string {
  return messages.map((m) => String(m.content ?? "").trim()).filter(Boolean).join("\n");
}

export function mergeStitchedText(priorText: string | undefined | null, additionalMessages: Pick<StitchableMessage, "content">[]): string {
  const additionalText = stitchedTextFor(additionalMessages);
  return [priorText ?? "", additionalText].filter(Boolean).join("\n");
}

export function partitionUnstitchedByContactAuthority<T extends { id: string; contact_id: string | null | undefined }>(
  messages: T[],
): { stitchable: T[]; rejectedIds: string[] } {
  const stitchable: T[] = [];
  const rejectedIds: string[] = [];
  for (const message of messages) {
    if (typeof message.contact_id === "string" && message.contact_id.trim().length > 0) stitchable.push(message);
    else rejectedIds.push(message.id);
  }
  return { stitchable, rejectedIds };
}
